                check(Math.abs(s.viewport.width*s.scale-s.width)<1&&Math.abs(s.viewport.height*s.scaleY-s.height)<1,"Layout fills viewport at scale "+requested+" "+page);
                if(page.equals("title")){var account=find(s,"Account and friends",AbstractWidget.class);check(account.getX()==26,"Account rail stays at left edge");var play=find(s,"Singleplayer",AbstractWidget.class);check(play.getX()>s.viewport.width/2-250&&play.getX()<s.viewport.width/2,"Main actions remain centered in the full panel");}
